def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after +)
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = None

        # Split off pre-release (after -)
        if '-' in v:
            version_part, prerelease = v.split('-', 1)
        else:
            version_part = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert identifiers: numeric ones become (0, int), others become (1, str)
            parsed_pre = []
            for ident in prerelease_identifiers:
                if ident.isdigit():
                    parsed_pre.append((0, int(ident)))
                else:
                    parsed_pre.append((1, ident))
        else:
            parsed_pre = None

        return (major, minor, patch, prerelease_identifiers if prerelease else None, parsed_pre)

    def sort_key(item):
        version, original_index = item
        major, minor, patch, prerelease_ids, parsed_pre = parse_version(version)

        # For sorting:
        # 1. Compare MAJOR.MINOR.PATCH numerically
        # 2. Version without pre-release sorts after version with pre-release
        #    (so we use False for no pre-release, True for pre-release)
        # 3. Pre-release identifiers compared as tuples

        if parsed_pre is None:
            # No pre-release: sorts after any pre-release
            pre_tuple = (False,)
        else:
            # Has pre-release: sorts before any no pre-release
            pre_tuple = (True, tuple(parsed_pre))

        return (major, minor, patch, pre_tuple, original_index)

    # Add original indices to maintain stability
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for v, _ in sorted_versions]

